	@Test
	void statementIndexReindexPreservesVariableLengthKeysAfterColdReopen() throws Exception {
		var factory = SimpleValueFactory.getInstance();
		var store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,posc,ospc")
				.setTripleTermIndexes("spoc,cspo"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		Set<Statement> expected = new HashSet<>();
		try (var connection = repository.getConnection()) {
			Set<Statement> explicit = new HashSet<>();
			Set<Statement> inferred = new HashSet<>();
			connection.begin();
			for (int index = 0; index < 320; index++) {
				Resource subject = factory.createIRI("urn:statement-reindex:subject:" + index);
				IRI predicate = factory.createIRI("urn:statement-reindex:predicate:" + index % 17);
				Value object = index % 2 == 0
						? factory.createIRI("urn:statement-reindex:object:" + index)
						: factory.createLiteral("statement-reindex-object-" + index);
				Resource context = index % 3 == 0 ? factory.createIRI("urn:statement-reindex:context:" + index % 11)
						: null;
				explicit.add(factory.createStatement(subject, predicate, object, context));
			}
			connection.add(explicit);
			connection.commit();
			try (var sink = store.getBackingStore().getInferredSailSource().sink(IsolationLevels.NONE)) {
				for (Statement statement : explicit) {
					Resource subject = factory.createIRI(statement.getSubject().stringValue() + ":inferred");
					Statement row = factory.createStatement(subject, statement.getPredicate(), statement.getObject(),
							statement.getContext());
					sink.approve(row.getSubject(), row.getPredicate(), row.getObject(), row.getContext());
					inferred.add(row);
				}
				sink.flush();
			}
			expected.addAll(explicit);
			expected.addAll(inferred);
			assertEquals(expected, QueryResults.asSet(connection.getStatements(null, null, null, true)));
		} finally {
			repository.shutDown();
		}

		repository = new SailRepository(new LmdbStore(directory.toFile(),
				new LmdbStoreConfig("cosp").setTripleTermIndexes("spoc,cspo")));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertEquals(expected, QueryResults.asSet(connection.getStatements(null, null, null, true)));
		} finally {
			repository.shutDown();
		}
		repository = new SailRepository(new LmdbStore(directory.toFile(),
				new LmdbStoreConfig("cosp").setTripleTermIndexes("spoc,cspo")));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertEquals(expected, QueryResults.asSet(connection.getStatements(null, null, null, true)));
		} finally {
			repository.shutDown();
		}
		assertEquals(320, LmdbCompatibilityFixtures.nativeTripleEntryCount(directory,
				TripleIndex.nativeDatabaseName("cosp", true)));
		assertEquals(320, LmdbCompatibilityFixtures.nativeTripleEntryCount(directory,
				TripleIndex.nativeDatabaseName("cosp", false)));
	}

	@Test
	void cspoFirstReindexDoesNotResurrectRetiredTripleTerms() throws Exception {
		var factory = SimpleValueFactory.getInstance();
		IRI predicate = factory.createIRI("urn:retired-reindex:predicate");
		IRI subject = factory.createIRI("urn:retired-reindex:subject");
		var term = factory.createTripleTerm(factory.createIRI("urn:retired-reindex:inner"), predicate,
				factory.createLiteral("retired triple term"));
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(),
				LmdbV6InteroperabilityTest.config(false).setTripleTermIndexes("cspo")));
		repository.init();
		long termId;
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(subject, predicate, term);
			connection.commit();
			termId = ((ValueStore) repository.getValueFactory()).getId(term);
			assertThat(termId).isNotEqualTo(org.eclipse.rdf4j.sail.lmdb.model.LmdbValue.UNKNOWN_ID);
			var backing = ((LmdbStore) repository.getSail()).getBackingStore();
			try (var snapshot = backing.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT)) {
				connection.begin(IsolationLevels.SNAPSHOT_READ);
				connection.remove(subject, predicate, term);
				connection.commit();
				assertThat(QueryResults.asList(snapshot.getStatements(subject, predicate, term)))
						.hasSize(1);
			}
		} finally {
			repository.shutDown();
		}
		assertTrue(LmdbCompatibilityFixtures.nativeGet(directory, "retired_ids",
				LmdbCompatibilityFixtures.unsigned(termId)) != null,
				"The original cspo-first store must retain the real retired owner before reindexing");

		repository = new SailRepository(new LmdbStore(directory.toFile(),
				LmdbV6InteroperabilityTest.config(false).setTripleTermIndexes("posc")));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertEquals(0, connection.size());
			assertEquals(org.eclipse.rdf4j.sail.lmdb.model.LmdbValue.UNKNOWN_ID,
					((ValueStore) repository.getValueFactory()).getId(term));
		} finally {
			repository.shutDown();
		}
		repository = new SailRepository(new LmdbStore(directory.toFile(),
				LmdbV6InteroperabilityTest.config(false)));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertEquals(0, connection.size());
		} finally {
			repository.shutDown();
		}
		assertIndexes(Set.of("spoc", "cspo", "posc"));
	}

	private void writeAndClose(String termIndexes, boolean add, boolean inline) throws Exception {
		LmdbStoreConfig config = LmdbV6InteroperabilityTest.config(inline).setTripleTermIndexes(termIndexes);
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
		var vf = SimpleValueFactory.getInstance();
		var predicate = vf.createIRI("urn:index:predicate");
		var term = vf.createTripleTerm(vf.createIRI("urn:index:inner"), predicate, vf.createLiteral("indexed"));
		try (var connection = repository.getConnection()) {
			if (add) {
				connection.begin();
				connection.add(vf.createIRI("urn:index:outer"), predicate, term);
				for (int index = 0; index < 320; index++) {
					var subject = vf.createIRI("urn:index:inner:" + index);
					var leaf = vf.createTripleTerm(subject, predicate,
							vf.createLiteral("indexed-value-" + index));
					var nested = vf.createTripleTerm(subject, predicate, leaf);
					connection.add(vf.createIRI("urn:index:outer:" + index), predicate, nested);
				}
				connection.commit();
			}
			assertTrue(connection.hasStatement(vf.createIRI("urn:index:outer"), predicate, term, false));
			if (add) {
				assertEquals(321, connection.size());
			}
			try (RecordIterator terms = ((ValueStore) repository.getValueFactory()).getTripleTerms(-1, -1, -1)) {
				assertTrue(terms.next() != null);
			}
		} finally {
			repository.shutDown();
		}
	}

	private void assertIndexes(Set<String> terms) throws Exception {
		var properties = properties(directory, "store.properties");
		assertEquals("2", properties.getProperty("version"));
		assertEquals(Set.of("spoc", "posc", "ospc"),
				TripleIndex.parseIndexSpecList(properties.getProperty("triple-indexes")));
		assertEquals(terms, TripleIndex.parseIndexSpecList(properties.getProperty("triple-term-indexes")));
	}
